OVERVIEW: This file contains the main functionality of the DE-10 SECURITY SYSTEM. 
The goal of this project is to create a security system inspired by the online 
captcha puzzles. Successful interaction with the system unlocks access, while an 
unsuccessful interaction triggers an alarm that can drive away intruders.

DESCRIPTION: An image is shown on the VGA monitor. The user has to input the number 
of objects in the image using the pushbuttons (ex. An image of traffic lights are 
shown. How many traffic lights are present?). Successful input displays a PASS on 
the hex display, while a unsuccessful input displays a FAIL on the hex display, 
while also sounding an alarm via a speaker connected to the DE-10 Standard FPGA Board.

INPUTS (2): Pushbuttons for answer input, key switches for resetting the system after 
pass/fail and triggering the round(s).

OUTPUTS (4): VGA monitor to display image(s), hex displays for text, LEDs for countdown 
timer and alarm, and speaker to trigger alarm sound.
*/

.global _start
_start:
	/* initialize addresses */
	ldr sp, =0x800000					// set stack pointer to the top of usable memory
	ldr r12, =MPCORE_PRIV_TIMER			// load address of cortex-a9 private timer into r12
	ldr r11, =LED_BASE					// load address of LEDs into r11
	ldr r10, =SEG_BASE0					// load address of the first four 7seg displays into r10
	ldr r8, =SW_BASE					// load address of switches into r8
	ldr r7, =SEG_BASE1					// load address of the last two 7seg displays into r7
	ldr r5, =KEY_BASE					// load address of push buttons into r5

	/* initialize timer registers */
	mov r0, #0			 				// hundredths
	mov r1, #0							// seconds
	
	/* initialize LEDs to blank */
	str r0, [r11]	
	
	/* initialize round counter */
	mov r3, #0
	
	/* note: r4 will act as the scratch register for storing intermediate values */

	/* setup hardware timer */
	ldr r4, =TIMEOUT					// set a timeout of 0.01s
	str r4, [r12]						// store timeout value into to the load register
	mov r4, #0b01						// prepare a '1' in binary
	str r4, [r12, #0xC] 				// clear timer bit by storing '1' to the status register
	mov r4, #0b011						// enable, auto-reload, no interrupt
	str r4, [r12, #0x08]				// store the behavior to the clock's control register
	
	/* reset 7seg displays */
	str r0, [r10]						// clear SEG_BASE0 by writing '0'
	str r0, [r7]						// clear SEG_BASE1 by writing '0'
	ldr r4, =seg03_table				// load the word _EADY into the scratch register
	ldr r4, [r4, #16]
	str r4, [r10]						// store _EADY into SEG_BASE0
	ldr r4, =seg45_table				// load the word R____ into the scratch register
	ldr r4, [r4, #16]
	str r4, [r7]						// store R____ into SEG_BASE0
	/* after the above code is run, READY will be shown on the hex displays */
	
	/* reset vga monitor */
	ldr r4, =info						// load the hex values necessary to display instructions on the vga monitor 
	bl _fill_colour						// run the subroutine to fill all pixels of the vga to the chosen image

/* after initiatization is complete, we will wait for the user to start their random test */
_read_switch:
	ldr r4, [r8]						// load the state of the switches into the scratch register
	tst r4, #1							// has the user triggered sw0?
	beq _read_switch					// if not, keep waiting

_load_test:	
	/* if sw0 is triggered, start the test */
	ldr r2, =0x3FF						// LED starting pattern (0b1111111111)
	str r2, [r11]						// turn on all LEDs
	str r0, [r10]						// clear SEG_BASE0
	str r0, [r7]						// CLEAR SEG_BASE1
	
	/* now that the test has started, we need to pick a random image to test on */
	ldr r8, [r12, #4]					// read the current counter register of the private timer
	and r8, r8, #0x30000				// perform an ADD operation with it to get a 'random' number
	lsr r8, #16							// right-shift the result to get a range of numbers btwn 0-7
	
    ldr r4, =image_table				// load VGA image
    ldr r4, [r4, r8, lsl #2]			// equivalent to ldr r4, [image_table, r8 * 4]
    bl _fill_colour						// run the subroutine to fill all pixels of the vga to the chosen image 
	
    ldr r4, =seg03_table				// load hex 0-3
    ldr r4, [r4, r8, lsl #2]			// equivalent to ldr r1, [seg03_table, r8 * 4]
    str r4, [r10]						// display to 7seg
    
    ldr r4, =seg45_table				// load hex 4-5
    ldr r4, [r4, r8, lsl #2]			// equivalent to ldr r1, [seg45_table, r8 * 4]
    str r4, [r7]						// display to 7seg			
	
/* all roads lead back to _main_loop */
_main_loop:
	bl _start_timer						// run the subroutine to increment the timer
	bl _check_choice					// run the subroutine to check the user's answer to the test
	
	/* reset the timer if one second has passed */
	cmp r1, #1							// has one second passed?
	moveq r1, #0						// if so, reset minutes to zero
	moveq r0, #0						// and reset seconds to zero
	/* run the subroutine to visually show that a second has passed and to check if the test time 
		limit has passed */
	bleq _stop_timer					
	
	b _main_loop						// if one second has not passed, loop
	
/* subroutine responsible for incrementing the timer */
_start_timer:
	push {r9, r10, r11, r12} 			// reuse registers for start_timer subroutine

	ldr r11, [r12, #0xC]				// check the status register of the timer
	cmp r11, #1							// has 0.01s passed?
	
	addeq r0, r0, #1					// if so, increment the seconds register by 0.01s 
	
	// calculate seconds
	ldr r10, =100						// load 100 into r10
	cmp r0, r10							// has the seconds register been incremented 100 times?
	addge r1, r1, #1 					// if so, increment the number of seconds by 1
	movge r0, #0 						// reset the number of 0.01 seconds that have passed
	
	// reset timer flag bit
	mov r9, #0b01 						// prepare a '1' in binary
	str r9, [r12, #0xC]					// clear timer bit by storing '1' to the status register
	
	pop {r9, r10, r11, r12}				// bring back original values for registers
	bx lr 								// back to _main_loop
	
/* subroutine responsible for visually showing that a second has passed and to check if the test time 
	limit has passed */
_stop_timer:
	push {lr}
	/* once a second has passed, decrement an LED */
	lsr r2, #1							// decrement LEDs
	str r2, [r11]						// display the decremented LED pattern
	
	bl _play_beep            			// play the 0.1s confirmation beep
	pop {lr}
	cmp r2, #0							// are there any more LEDs lit up?
	
	/* if not, start the FAIL procedure */
	ldreq r4, =fail						// load the hex values necessary to display FAIL the vga monitor  
	bleq _fill_colour					// run the subroutine to fill all pixels of the vga to the chosen image
	moveq r0, #0						// prepare a '0' in binary
	streq r0, [r7]						// use it to clear SEG_BASE1			
	ldreq r4, =0x71773038				// load the word FAIL
	streq r4, [r10]						// display it on SEG_BASE0
	beq _end_fail						// run the subroutine to show the user that they've failed the test
	
	bx lr 								// back to _main_loop

/* subroutine to play a short 0.1s beep */
_play_beep:
    push {r0-r4, r6, r9, lr}
    ldr r6, =AUDIO_BASE
    mov r0, #0x20000000      // volume
    ldr r4, =4800            // 4800 samples = 0.1s at 48kHz
    mov r1, #48              // pitch (half-period)
    mov r2, r1               // half-period counter

_beep_loop:
    ldr r9, [r6, #4]         // check FIFO
    ands r9, r9, #0xff000000 
    beq _beep_loop           // wait if full
    
    str r0, [r6, #8]         // write left
    str r0, [r6, #12]        // write right
    
    subs r2, r2, #1
    moveq r2, r1             // reset half-period
    negeq r0, r0             // invert square wave
    
    subs r4, r4, #1          // decrement sample counter
    bne _beep_loop
    
    pop {r0-r4, r6, r9, lr}
    bx lr

/* subroutine responsible for filling the vga monitor with the correct pixels to display can image */
/* optimized subroutine to fill the vga monitor */
_fill_colour:
    push {r0-r5, r8-r10, lr}            // reuse registers for subroutine
    
    mov r10, r4                         // r10 = source pointer (image data)
    ldr r0, =PIX_BASE                   // r0 = destination base address (vga)
    
    mov r9, #0                          // y-coordinate counter
    
	1:  /* outer loop (rows) */
		// calculate the start of the current row in the vga buffer
		// row_offset = y << 10 (assuming BYTES_PER_ROW is 10)
		lsl r1, r9, #BYTES_PER_ROW          
		add r5, r0, r1                 	// r5 = pointer to the start of the current row in vga

		mov r8, #0                     	// reset x-counter for the new row

		2:  /* inner loop (pixels) */
			ldrh r2, [r10], #2         	// load 16-bit color AND post-increment source pointer
			strh r2, [r5], #2           // store 16-bit color AND post-increment destination pointer

			add r8, r8, #1              // increment x
			cmp r8, #WIDTH              // reached 320?
			bne 2b                      // loop x

			add r9, r9, #1              // increment y
			cmp r9, #HEIGHT             // reached 240?
			bne 1b                      // loop y

    pop {r0-r5, r8-r10, lr}				// bring back original register values
    bx lr								// return to the loop it was called from
	
/* subroutines responsible for checking if the user has made an input during the test */
_check_choice:
	push {r2, r4, r5, r8, lr}			// save some registers by pushing them onto the stack
	ldr r4, [r5]						// read the state of the push buttons
	ands r4, r4, #0xF					// mask to show only KEY0-KEY3
	// if no buttons have been pressed, pop the registers early and return to _main_loop
	beq _exit_choice					
	
	/* if a button was pressed, look up the answer in the table */
    ldr r2, =answer_table               // load table base
    ldr r2, [r2, r8, lsl #2]            // get the specific answer for image in r8

	tst r4, r2							// did they press the correct KEY corresponding to the choice?
	
	/* procedure for incorrect choice */
	moveq r2, #0						// clear LEDs by preparing a '0'
	beq _fail							// pop the registers early and go to _stop_timer
	
	/* procedure for correct choice */
	movne r0, #0						// prepare a '0'
	strne r0, [r7]						// use it to clear SEG_BASE1
	ldrne r4, =0x73776D6D				// load the word PASS
	strne r4, [r10]						// display PASS on SEG_BASE0
	bne _pass							// run the subroutine to show the user that they've passed the test

	pop {r2, r4, r5, r8, lr}			// bring back original register values by popping them from the stack
	bx lr								// back to _main_loop

/* sub-subroutine to work around the lack of conditional execution codes available for the pop instruction */
_exit_choice:
	pop {r2, r4, r5, r8, lr}			// bring back original register values by popping them from the stack
	bx lr								// back to _main_loop
	
/* sub-subroutine to work around the lack of conditional execution codes available for the pop instruction */
_fail:
	pop {r2, r4, r5, r8, lr}			// bring back original register values by popping them from the stack
	/* clear hardware */
    mov r0, #0
    str r0, [r11]                       // turn off all LEDs
    str r0, [r7]                        // clear SEG_BASE1
    
    /* update Displays */
    ldr r4, =fail                       // point to FAIL image data
    bl _fill_colour                     // update VGA
    
    ldr r4, =0x71773038                 // hex pattern for "FAIL"
    str r4, [r10]                       // display on SEG_BASE0
    
    /* enter alarm loop */
    b _end_fail						

/* sub-subroutine to work around the lack of conditional execution codes available for the pop instruction */
_pass:
    pop {r2, r4, r5, r8, lr}
    add r3, r3, #1         				// increment the round counter
    cmp r3, #3              			// have we reached 3 rounds?
    beq _end_pass           			// if yes, go to the final win screen

    /* if not 3, show PASS screen then loop for a new round */
    ldr r4, =pass           
    bl _fill_colour         

    /* small delay so the user sees the PASS screen */
    ldr r4, =30000000
    delay_lp: subs r4, r4, #1
       bne delay_lp

    b _load_test          				// next round!

/* loop that plays when the user makes the correct choice during the test */
_end_pass:
    ldr r4, =unlocked            		// display a "UNLOCKED" vga image
    bl _fill_colour
    
    /* display "OPEN" 7seg display */
  	ldr r4, =0x3F737937					
	str r4, [r10]						
    
_wait_for_reset:
    ldr r8, =SW_BASE					// load address of switches into r8
	ldr r4, [r8]						// load state of switches into the scratch register
	tst r4, #1							// is sw0 off?
	bne _wait_for_reset					// if not, loop
	ldr r4, [r5]						// if so, load the state of push buttons into the scratch register
	cmp r4, #3							// is KEY0 and KEY1 on?
	bne _wait_for_reset					// if not, loop
	
	b _start							// if so, reset the program by going to _start

/* loop that plays when the user makes the incorrect choice during the test */
_end_fail:
    ldr r6, =AUDIO_BASE    				// load the address of the audio core into r6
    ldr r8, =SW_BASE    				// load address of switches into r8
    ldr r5, =KEY_BASE    				// load address of push buttons into r5
	ldr r12, =0x2AA						// prepare LED pattern of 1010101010
    
    ldr r10, =0x20000000   				// load static volume value into r10
    mov r0, r10            				// start with volume ON in r0
    mov r7, #1             				// r7 is our toggle flag for volume (1 = on, 0 = off)
    
    mov r1, #48            				// load pitch value (half-period length) into r1
    mov r2, r1             				// initialize half-period counter
    ldr r4, =200000        				// pulse counter (~0.5s beeps, should be tweaked based on speed of hardware)

/* the pulse logic for the audio core which allows it to beep */
_fail_loop:
    subs r4, r4, #1						// decrement pulse counter by 1
    bne _audio_out         				// if not zero, skip the toggle

    /* toggle logic when the pulse counter hits 0 */
    ldreq r4, =200000      				// reset pulse counter
    eor r7, r7, #1         				// flip toggle flag
    cmp r7, #1							// toggle flag comparison with '1'
	streq r12, [r11]       				// if flag is 1, write 0101010101 to the LEDs
	lsleq r12, r12, #1					// after writing to the LEDs, left shift the LED pattern
	
    strne r12, [r11]        			// if flag is 0, write 0101010101 to the LEDs
	lsrne r12, r12, #1					// after writing to the LEDs, right shift the LED pattern
	
    moveq r0, r10          				// If flag is 1, set volume to 0x20000000
    movne r0, #0           				// If flag is 0, set volume to 0 (silence)

/* function responsible for playing the audio */
_audio_out:
    ldr r9, [r6, #4]       				// read the first-in-first-out (FIFO) register
    ands r9, r9, #0xff000000 			// check if the right channel (and by extension, the left channel) has space for audio samples
    beq _input_check       				// if the FIFO is full, skip writing
    
	/* if the FIFO is not full, let's write some audio samples into it */
    str r0, [r6, #8]       				// write the volume to left channel (might be 0 depending on the toggle flag)
    str r0, [r6, #12]      				// write the volume to right channel (might be 0 depending on the toggle flag)
    
    subs r2, r2, #1						// decrement half-period counter: has it become zero?
    moveq r2, r1           				// if so, reset the half-period counter
    negeq r0, r0           				// invert the volume to make a square wave oscillation

_input_check:
    ldr r9, [r8]      					// load state of switches into r9 (our new scratch register)    
    tst r9, #1             				// is sw0 off?
    bne _fail_loop         				// if not, loop to _fail_loop
    ldr r9, [r5]           				// if so, load the state of push buttons into the scratch register
    cmp r9, #3             				// is KEY0 on?
    bne _fail_loop         				// if not, loop to _fail_loop
    
    b _start							// if so, reset the program by going to _start

.data
image_table: // image LUT used in _load_image subroutine
	.word bus0, car1, cycle2, light3

answer_table: // captcha image answers used in _check_choice subroutine
	.word 1, 2, 4, 8

// words in order: BUSSES, CARS, CYCLES, LIGHTS, READY
seg03_table: 	.word 0x6D6D796D, 0x3977316D, 0x3938796D, 0x6F74786D, 0x79775E6E
// words in order: BUSSES, [BLANK], CYCLES, LIGHTS, READY
seg45_table: 	.word 0x00007C3E, 0x00000000, 0x0000396E, 0x00003830, 0x00000031

// the following lists are the VGA buffer values for the images to be displayed on the VGA monitor
