.equ LED_BASE, 0xFF200000				// address of the LEDs
.equ PIX_BASE, 0xC8000000				// address of the vga monitor
.equ AUDIO_BASE, 0xFF203040				// address of the audio core
.equ SW_BASE, 0xFF200040				// address of the switches
.equ SEG_BASE0, 0xFF200020				// address of the first four 7seg displays
.equ SEG_BASE1, 0xFF200030				// address of the last two 7seg displays
.equ MPCORE_PRIV_TIMER, 0xFFFEC600		// address of the cortex-a9 private timer
.equ TIMEOUT, 1999999					// timeout value (see lab2 for math behind this number)
.equ WIDTH, 320							// width of vga monitor
.equ HEIGHT, 240						// height of vga monitor
.equ BYTES_PER_ROW, 10					// 2^10 = 1024 bytes per row
.equ BYTES_PER_PIXEL, 1					// 2^1 = 2 bytes per pixel (rgb565)